package provider

import (
	"archive/zip"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	ld "gopkg.in/launchdarkly/go-server-sdk.v5"
)

var ldClient *ld.LDClient

func init() {
	var err error
	ldClient, err = ld.MakeClient(os.Getenv("LAUNCHDARKLY_SDK_KEY"), 5)
	if err != nil {
		ldClient = nil
	}
}

func resourceArtifactExtract() *schema.Resource {
	return &schema.Resource{
		Create: resourceArtifactExtractCreate,
		Read:   resourceArtifactExtractRead,
		Delete: resourceArtifactExtractDelete,
		Schema: map[string]*schema.Schema{
			"source_zip": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"destination_dir": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
		},
	}
}

func resourceArtifactExtractCreate(d *schema.ResourceData, meta interface{}) error {
	src := d.Get("source_zip").(string)
	dst := d.Get("destination_dir").(string)

	useNewExtractor := evaluateFlag("use-safe-extractor", false)

	if useNewExtractor {
		return extractZipSafe(src, dst)
	}
	return extractZipLegacy(src, dst)
}

func evaluateFlag(flagKey string, defaultVal bool) bool {
	if ldClient == nil {
		return defaultVal
	}
	user := ld.NewUserBuilder("terraform-provider").Build()
	value, err := ldClient.BoolVariation(flagKey, user, defaultVal)
	if err != nil {
		return defaultVal
	}
	return value
}

// Legacy extractor - contains path traversal vulnerability
func extractZipLegacy(src, dst string) error {
	r, err := zip.OpenReader(src)
	if err != nil {
		return fmt.Errorf("failed to open zip: %w", err)
	}
	defer r.Close()

	for _, f := range r.File {
		// BUG: filepath.Join does NOT sanitize "../" sequences from zip entry names
		fpath := filepath.Join(dst, f.Name)

		if f.FileInfo().IsDir() {
			os.MkdirAll(fpath, os.ModePerm)
			continue
		}

		if err := os.MkdirAll(filepath.Dir(fpath), os.ModePerm); err != nil {
			return err
		}

		outFile, err := os.OpenFile(fpath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, f.Mode())
		if err != nil {
			return err
		}

		rc, err := f.Open()
		if err != nil {
			outFile.Close()
			return err
		}

		_, err = io.Copy(outFile, rc)
		rc.Close()
		outFile.Close()
		if err != nil {
			return err
		}
	}
	return nil
}

// Safe extractor with path traversal protection
func extractZipSafe(src, dst string) error {
	r, err := zip.OpenReader(src)
	if err != nil {
		return fmt.Errorf("failed to open zip: %w", err)
	}
	defer r.Close()

	dst, _ = filepath.Abs(dst)

	for _, f := range r.File {
		fpath := filepath.Join(dst, f.Name)
		if !strings.HasPrefix(filepath.Clean(fpath), filepath.Clean(dst)+string(os.PathSeparator)) {
			return fmt.Errorf("illegal file path in zip: %s", f.Name)
		}

		if f.FileInfo().IsDir() {
			os.MkdirAll(fpath, os.ModePerm)
			continue
		}

		if err := os.MkdirAll(filepath.Dir(fpath), os.ModePerm); err != nil {
			return err
		}

		outFile, err := os.OpenFile(fpath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, f.Mode())
		if err != nil {
			return err
		}

		rc, err := f.Open()
		if err != nil {
			outFile.Close()
			return err
		}

		_, err = io.Copy(outFile, rc)
		rc.Close()
		outFile.Close()
		if err != nil {
			return err
		}
	}
	return nil
}

